\begin{itemchoice}
			\itemch Tổng số hình: $3 + 4 = 7$ hình (Đúng).\
			\itemch Số hình tròn (3) ít hơn số hình tam giác (4) nên phát biểu nhiều hơn là Sai.\
			\itemch Số hình tam giác nhiều hơn số hình tròn: $4 - 3 = 1$ hình (Đúng).\
			\itemch Có 4 hình tam giác, bớt 2 hình thì còn $4 - 2 = 2$ hình, phát biểu còn 5 hình là Sai.\
		\end{itemchoice}
